__NUXT_JSONP__("/sp/how-to-apply-for-a-student-visa", {data:[{details:{slug:"sp",pageTitle:"Cómo solicitar una visa de estudiante | Mentor Language Institute",pageDescription:"Hay varios pasos para solicitar una visa de estudiante (visa F1). ",title:"Cómo solicitar una visa de estudiante",subtitle:["Hay varios pasos para solicitar una visa de estudiante (visa F1). El orden de estos pasos y cómo los completa puede variar según la Embajada o el Consulado de los EE.UU. en cada país. Consulte las instrucciones en el \u003Ca title=\"sitio web de la embajada o el consulado\" href=\"http:\u002F\u002Fwww.usembassy.gov\u002F\" target=\"_blank\"\u003E\u003C\u002Fa\u003E",null,"El video de instrucciones para la visa de estudiante a continuación le dará un procedimiento general para solicitar y obtener una visa de estudiante."],yt_link:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002F_Wi7kL4bePk",other_description:["Puede descargar el material de presentación con el enlace a continuación.","\u003Cstrong\u003EDescargue\u003C\u002Fstrong\u003E \u003Ca href=\"\u002Fdocuments\u002FHow_to_apply_for_a_student_visa_Spanish_2021.pdf\" target=\"_blank\"\u003E\u003Cstrong\u003Elos materiales de presentación Cómo solicitar una visa de estudiante.\u003C\u002Fstrong\u003E\u003C\u002Fa\u003E"],dir:"\u002Fhow-to-apply-for-a-student-visa",path:"\u002Fhow-to-apply-for-a-student-visa\u002Fsp",extension:".json",createdAt:"2026-10-22T16:31:29.678Z",updatedAt:"2025-05-26T12:06:27.788Z"}}],fetch:{},mutations:void 0});